<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';import {echarts} from '../../config/echarts'
const props=defineProps({data:{type:Array,default:()=>[]}});const el=ref(),chart=ref();const option=computed(()=>({tooltip:{formatter:p=>`${p.data.name}<br/>支付金额 ¥${Number(p.data.value).toLocaleString()}<br/>支付订单 ${p.data.paidOrderCount}`},series:[{type:'treemap',roam:false,nodeClick:false,breadcrumb:{show:false},label:{show:true,formatter:'{b}\n¥{c}',color:'#fff'},itemStyle:{borderColor:'#091033',borderWidth:3,gapWidth:3},levels:[{color:['#173f8f','#176b8f','#315de8','#477ec7','#684fc4'],colorMappingBy:'value',itemStyle:{borderRadius:4}}],data:props.data.map(x=>({name:x.name,value:x.paidAmount,paidOrderCount:x.paidOrderCount}))}]}));const render=()=>chart.value?.setOption(option.value,true);onMounted(()=>{chart.value=echarts.init(el.value,'warehouse');render();addEventListener('resize',chart.value.resize)});watch(option,render,{deep:true});onBeforeUnmount(()=>chart.value?.dispose())
</script><template><div ref="el" class="chart" role="img" aria-label="店铺支付金额贡献矩形树图"></div></template>
